// Ported from SMS app: app/src/main/java/com/viswa2k/sms/classify/KeywordLists.kt (2026-10-25 snapshot)
package com.viswa2k.smsforwarder.classify

/**
 * The decoded keyword lists of spec 05a, bundled as `assets/keywords.json` (generated by
 * `tools/extract_keywords.py`). Lists are index-addressed exactly as 05a prints them, because rules
 * refer to `list[index]`; empty entries are kept.
 *
 * Look a list up by its getter name (`getNewfraud01`, `getStringOSP1`, `CASENO14`) or by its pref key
 * (`scmcase1`, `getStringOSP1`, `case14`). Shared by the classifier (Task 3) and the finance parser
 * (Task 10).
 */
class KeywordLists(
    private val lists: Map<String, List<String>>,
    private val prefKeys: Map<String, String> = emptyMap(),
) {
    /** All getter names. */
    val names: Set<String> get() = lists.keys

    /** The list named [name] (getter or pref key), or an empty list if unknown. */
    operator fun get(name: String): List<String> = lists[name] ?: prefKeys[name]?.let { lists[it] } ?: emptyList()

    /** True if [name] (getter or pref key) exists. */
    fun has(name: String): Boolean = name in lists || prefKeys[name]?.let { it in lists } == true

    /** Item [index] of list [name], or "" when out of range (the original indexed blindly). */
    fun item(name: String, index: Int): String = get(name).getOrElse(index) { "" }

    /** Items [indices] of list [name], skipping blanks. */
    fun items(name: String, indices: Iterable<Int>): List<String> =
        indices.map { item(name, it) }.filter { it.isNotBlank() }

    companion object {
        /** Empty lists (classifier falls back to its built-in vocabulary). */
        val EMPTY = KeywordLists(emptyMap())

        /** Parses the `keywords.json` document (`{"lists": {...}, "prefKeys": {...}}`). */
        fun parse(json: String): KeywordLists {
            val root = MiniJson.parse(json) as? Map<*, *> ?: error("keywords.json: root is not an object")
            val lists = (root["lists"] as? Map<*, *> ?: error("keywords.json: no lists")).entries.associate { (k, v) ->
                k as String to (v as List<*>).map { it as String }
            }
            val prefKeys = (root["prefKeys"] as? Map<*, *>).orEmpty().entries.associate { (k, v) ->
                k as String to v as String
            }
            return KeywordLists(lists, prefKeys)
        }

        /** Loads from [source]. */
        fun load(source: KeywordSource): KeywordLists = parse(source.readText())
    }
}

/**
 * Where the keyword JSON comes from: the APK asset at run time (`data.repo.AssetKeywordSource`), or a
 * file in unit tests.
 */
fun interface KeywordSource {
    fun readText(): String

    companion object {
        /** Asset path inside the APK. */
        const val ASSET_NAME = "keywords.json"
    }
}
